create extension if not exists pgcrypto;
create type public.transaction_kind as enum ('income','expense','investment','transfer');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz default now());
create table public.accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,institution text,type text not null default 'digital',initial_balance_cents bigint not null default 0,color text,is_active boolean not null default true,created_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,kind public.transaction_kind not null,color text,icon text,is_archived boolean not null default false,created_at timestamptz default now(),unique(user_id,name,kind));
create table public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind public.transaction_kind not null,subtype text,amount_cents bigint not null check(amount_cents>0),category_id uuid references public.categories(id) on delete set null,account_id uuid references public.accounts(id) on delete set null,destination_account_id uuid references public.accounts(id) on delete set null,description text,notes text,occurred_at date not null default current_date,created_at timestamptz default now(),check((kind='transfer' and account_id is not null and destination_account_id is not null and account_id<>destination_account_id) or kind<>'transfer'));
create table public.budgets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category_id uuid not null references public.categories(id) on delete cascade,month date not null,limit_cents bigint not null check(limit_cents>0),unique(user_id,category_id,month));
create table public.goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,target_cents bigint not null check(target_cents>0),current_cents bigint not null default 0,target_date date,created_at timestamptz default now());
create index transactions_user_date_idx on public.transactions(user_id,occurred_at desc);create index transactions_user_kind_idx on public.transactions(user_id,kind);
alter table public.profiles enable row level security;alter table public.accounts enable row level security;alter table public.categories enable row level security;alter table public.transactions enable row level security;alter table public.budgets enable row level security;alter table public.goals enable row level security;
create policy "profile owner" on public.profiles for all to authenticated using((select auth.uid())=id)with check((select auth.uid())=id);create policy "accounts owner" on public.accounts for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "categories owner" on public.categories for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "transactions owner" on public.transactions for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "budgets owner" on public.budgets for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "goals owner" on public.goals for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);
grant usage on schema public to authenticated;grant select,insert,update,delete on all tables in schema public to authenticated;
